def reduce_if_selected(path,raw):
 if path not in SOURCE_INPUTS:return raw
 if type(raw)is not bytes:raise ValueError('N05 media metadata bytes required')
 if hashlib.sha256(raw).hexdigest()!=SOURCE_INPUTS[path]:return raw
 if raw!=CURRENT_BYTES[path]:raise ValueError('N05 media inverse literal changed')
 restored=BASE_BYTES[path]
 if hashlib.sha256(restored).hexdigest()!=BASE_PINS[path]:raise ValueError('N05 media predecessor changed')
 return restored
def reduce_current(path,raw):
 if path not in SOURCE_INPUTS or type(raw)is not bytes or hashlib.sha256(raw).hexdigest()!=SOURCE_INPUTS[path]:raise ValueError('unreviewed current N05 media metadata')
 return reduce_if_selected(path,raw)

