def reduce_stageB(path,raw):
 if path not in SOURCE_INPUTS:return raw
 if type(raw)is not bytes or hashlib.sha256(raw).hexdigest()!=SOURCE_INPUTS[path]:raise ValueError('unknown Stage C source bytes')
 if raw!=CURRENT_BYTES[path]:raise ValueError('Stage C exact literal changed')
 old=STAGEB_BYTES[path]
 # Every old byte here comes from the actual signed Stage B public Git tree.
 return old

def reduce_previous_recipe(path,raw):
 # Test-only committed predecessor view; not used by source readers or runtime.
 if path not in PREVIOUS_RECIPE_BYTES:return raw
 if type(raw)is not bytes or raw!=PREVIOUS_RECIPE_BYTES[path]:raise ValueError("unknown previous signed recipe bytes")
 return BASE_BYTES[path]

def reduce_repair_recipe(path,raw):
 # Exact signed repaired recipe predecessor for a test-only historical view.
 if path not in REPAIR_RECIPE_BYTES:return raw
 if type(raw)is not bytes or raw!=REPAIR_RECIPE_BYTES[path]:raise ValueError('unknown signed repair recipe bytes')
 return BASE_BYTES[path]
